BEGIN;
CREATE TABLE IF NOT EXISTS bank_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES entities(id),bank_name varchar(255) NOT NULL,account_name varchar(255) NOT NULL,account_number_encrypted text NOT NULL,currency char(3) NOT NULL,gl_account_id uuid REFERENCES accounts(id),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bank_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bank_account_id uuid NOT NULL REFERENCES bank_accounts(id),external_id varchar(150),transaction_date date NOT NULL,description text,amount numeric(20,2) NOT NULL,currency char(3) NOT NULL,status varchar(20) NOT NULL DEFAULT 'UNMATCHED' CHECK(status IN ('UNMATCHED','SUGGESTED','MATCHED','EXCLUDED')),imported_at timestamptz NOT NULL DEFAULT now(),UNIQUE(bank_account_id,external_id));
CREATE TABLE IF NOT EXISTS bank_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bank_transaction_id uuid NOT NULL REFERENCES bank_transactions(id),ledger_transaction_id uuid NOT NULL REFERENCES ledger_transactions(id),confidence numeric(5,2) CHECK(confidence BETWEEN 0 AND 100),approved_by uuid REFERENCES users(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(bank_transaction_id,ledger_transaction_id));
CREATE INDEX IF NOT EXISTS ix_bank_tx_status_date ON bank_transactions(bank_account_id,status,transaction_date);
COMMIT;
